mapper.select:
select u.user_id, u.user_name, u.nick_name, u.grade, u.sex, u.phonenumber, u.join_class_time, c.class_name from sys_user u,ms_class c where u.class_id=c.class_id and u.del_flag='0'
and u.user_name like concat('%',#{userName},'%')
and u.grade=#{grade}
and u.class_id in
#{classId}
order by u.join_class_time desc
